const hotel1 = $fromAI.item.hotel1;
const hotel2 = $fromAI.item.hotel2;
const country = $fromAI.item.country || 'turkey';
const nights = $fromAI.item.nights || 7;
const adults = $fromAI.item.adults || 2;

const baseUrl = 'https://emikss.host/webhook/tour-search-unified';
const params = { country, nights, adults, children: 0, searchDays: 30 };

try {
  const [res1, res2] = await Promise.all([
    fetch(baseUrl, { method: 'POST', headers: {'Content-Type': 'application/json'}, body: JSON.stringify({...params, hotel: hotel1}) }).then(r => r.json()),
    fetch(baseUrl, { method: 'POST', headers: {'Content-Type': 'application/json'}, body: JSON.stringify({...params, hotel: hotel2}) }).then(r => r.json())
  ]);

  const tours1 = res1.results || [];
  const tours2 = res2.results || [];

  const best1 = tours1.length > 0 ? tours1.reduce((min, t) => t.price < min.price ? t : min, tours1[0]) : null;
  const best2 = tours2.length > 0 ? tours2.reduce((min, t) => t.price < min.price ? t : min, tours2[0]) : null;

  const comparison = {
    hotel1: {
      name: hotel1,
      totalTours: tours1.length,
      bestPrice: best1 ? `${best1.price} ${best1.currency || 'EUR'}` : 'нет туров',
      bestDate: best1 ? best1.date : null,
      bestMeal: best1 ? best1.meal : null,
      stars: best1 ? best1.stars : null,
      source: best1 ? best1.source : null
    },
    hotel2: {
      name: hotel2,
      totalTours: tours2.length,
      bestPrice: best2 ? `${best2.price} ${best2.currency || 'EUR'}` : 'нет туров',
      bestDate: best2 ? best2.date : null,
      bestMeal: best2 ? best2.meal : null,
      stars: best2 ? best2.stars : null,
      source: best2 ? best2.source : null
    },
    priceDifference: (best1 && best2) ? Math.abs(best1.price - best2.price) : null,
    cheaperHotel: (best1 && best2) ? (best1.price < best2.price ? hotel1 : hotel2) : null
  };

  return JSON.stringify(comparison, null, 2);
} catch (e) {
  return JSON.stringify({ error: 'Ошибка сравнения: ' + e.message });
}

